/// Crate-standard boxed-error result, aliased locally for brevity.
type Result<T> = std::result::Result<T, Box<dyn std::error::Error>>;

/// The operation attribute naming the vc-x1 run an operation belongs
/// to. A run is one vc-x1 invocation, and every operation it commits,
/// in every repo it opens, carries the same id, so the op log itself
/// says which operations one run made.
pub const RUN_ID_ATTRIBUTE: &str = "vc-x1-run";

/// The operation attribute carrying the run's command line, as jj's
/// own `args` attribute carries a `jj` command's.
pub const RUN_ARGS_ATTRIBUTE: &str = "vc-x1-args";

/// This process's run: its id and its command line, made at the first
/// transaction and the same for every one after.
struct Run {
    id: String,
    args: String,
}

/// The run, made on first use: a random id, and the command line
/// with each argument quoted as a shell word where it needs it.
fn run() -> &'static Run {
    static RUN: OnceLock<Run> = OnceLock::new();
    RUN.get_or_init(|| Run {
        id: format!("{:016x}", rand::random::<u64>()),
        args: std::env::args_os()
            .map(|arg| shell_word(&arg.to_string_lossy()))
            .collect::<Vec<_>>()
            .join(" "),
    })
}

/// This process's run id, the value of [`RUN_ID_ATTRIBUTE`] on every
/// operation it commits.
pub fn run_id() -> &'static str {
    &run().id
}

/// `arg` as a shell word: bare when plain, single-quoted otherwise.
fn shell_word(arg: &str) -> String {
    let plain = !arg.is_empty()
        && arg
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || "-_./=:@,+%".contains(c));
    if plain {
        arg.to_string()
    } else {
        format!("'{}'", arg.replace('\'', r"'\''"))
    }
}

/// Stamp `tx` with this process's run, so the operation it commits
/// says which vc-x1 run made it. Every transaction a session starts
/// takes it: [`RepoSession::start_tx`] and the three the snapshot
/// cycle starts on its own.
fn tag_run(tx: &mut Transaction) {
    let run = run();
    tx.set_attribute(RUN_ID_ATTRIBUTE.to_string(), run.id.clone());
    tx.set_attribute(RUN_ARGS_ATTRIBUTE.to_string(), run.args.clone());
}

