/// The operation attribute carrying the run's command line, as jj's
/// own `args` attribute carries a `jj` command's.
pub const RUN_ARGS_ATTRIBUTE: &str = "vc-x1-args";

/// This process's run: its id and its command line, made at the first
/// transaction and the same for every one after.
struct Run {
    id: String,
    args: String,
}

/// The run, made on first use: a random id, and the command line
/// with each argument quoted as a shell word where it needs it.
fn run() -> &'static Run {
    static RUN: OnceLock<Run> = OnceLock::new();
    RUN.get_or_init(|| Run {
        id: format!("{:016x}", rand::random::<u64>()),
        args: std::env::args_os()
            .map(|arg| shell_word(&arg.to_string_lossy()))
            .collect::<Vec<_>>()
            .join(" "),
    })
}

/// `arg` as a shell word: bare when plain, single-quoted otherwise.
fn shell_word(arg: &str) -> String {
    let plain = !arg.is_empty()
        && arg
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || "-_./=:@,+%".contains(c));
